// keys with no brand asset at all; they render as an initial disc. Listed so
// the fallback is deliberate, not a miss. Empty since 2026-08-23: the 17 that
// simple-icons lacked were sourced by hand (SOURCES.md). markFor still handles
// an unknown key, so a new catalogue entry degrades to an initial, never throws.
export const NO_MARK = [];

// deterministic hue from the key (FNV-1a over the key, mod 360), so the same
// connector always wears the same colour across renders and machines.
export function hueFor(key) {
  let h = 0x811c9dc5;
  for (const ch of String(key)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h % 360;
}

// markFor(key, label) ->
//   { kind: 'svg', svg, hex }       single-colour: CSS mask-image tinted with hex
//   { kind: 'img', src, hex }       multi-colour svg or png: plain <img src>
//   { kind: 'initial', letter, hue } no mark
// svg / src are data: URIs usable under the panel CSP.
export function markFor(key, label) {
  const m = MARKS[key];
  if (m && m.png) return { kind: 'img', src: m.png, hex: m.hex };
  if (m && m.img) return { kind: 'img', src: m.svg, hex: m.hex };
  if (m) return { kind: 'svg', svg: m.svg, hex: m.hex };
  const src = String(label || key || '?').trim();
  const letter = (src[0] || '?').toUpperCase();
  return { kind: 'initial', letter, hue: hueFor(key || src) };
}
